-- cet4 词库 batch1:freq_rank 前 3814 词
-- 生成: node scripts/vocab/ingest-toefl.mjs --bank=cet4 --limit=3814 --emit-sql
-- 数据源: skywind3000/ECDICT · MIT License (c) 2025 Linwei
-- ⚠️ 由 Aaron 执行。脚本本身从不写库。
--
-- 幂等性: vocab_words 走 ON CONFLICT (lower(headword))(索引 vocab_words_headword_uq),
--         vocab_word_banks 走 PK (word_id, bank_id)。重复跑不会产生重复行。
-- bank_id 用子查询取,不硬编码 uuid。

BEGIN;

-- ── 跑之前的基线 ──
SELECT 'BEFORE' AS stage,
       (SELECT count(*) FROM vocab_words) AS words,
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet4')) AS bank_links;

-- ① 词条
ON CONFLICT (lower(headword)) DO UPDATE
  SET pos        = COALESCE(EXCLUDED.pos, vocab_words.pos),
      freq_rank  = COALESCE(EXCLUDED.freq_rank, vocab_words.freq_rank),
      updated_at = now();

-- ② 挂到 cet4 词库
SELECT w.id, b.id
  FROM vocab_words w
  CROSS JOIN (SELECT id FROM vocab_banks WHERE code = 'cet4') b
 WHERE lower(w.headword) IN ('state', 'might', 'part', 'against', 'system', 'program', 'government', 'point', 'happen', 'area', 'national', 'fact', 'business', 'issue', 'provide', 'power', 'line', 'political', 'lose', 'however', 'law', 'include', 'continue', 'later', 'community', 'least', 'president', 'real', 'team', 'kid', 'lead', 'social', 'follow', 'centre', 'create', 'public', 'level', 'allow', 'add', 'art', 'war', 'history', 'within', 'result', 'win', 'research', 'guy', 'force', 'offer', 'education', 'although', 'toward', 'policy', 'process', 'consider', 'appear', 'actually', 'probably', 'human', 'sense', 'nation', 'interest', 'death', 'course', 'experience', 'reach', 'local', 'kill', 'remain', 'effect', 'control', 'perhaps', 'former', 'major', 'require', 'role', 'economic', 'effort', 'rate', 'drug', 'leader', 'voice', 'whole', 'police', 'finally', 'military', 'less', 'decision', 'explain', 'view', 'relationship', 'federal', 'difference', 'value', 'international', 'action', 'model', 'society', 'tax', 'director', 'position', 'player', 'especially', 'record', 'special', 'space', 'support', 'event', 'official', 'couple', 'site', 'project', 'hit', 'base', 'activity', 'court', 'produce', 'oil', 'situation', 'industry', 'figure', 'image', 'phone', 'data', 'recent', 'describe', 'product', 'patient', 'test', 'movie', 'certain', 'personal', 'technology', 'step', 'type', 'attention', 'republican', 'organization', 'source', 'choose', 'cause', 'century', 'evidence', 'culture', 'billion', 'chance', 'energy', 'realize', 'period', 'available', 'likely', 'opportunity', 'term', 'condition', 'choice', 'rule', 'administration', 'congress', 'campaign', 'material', 'population', 'economy', 'medical', 'church', 'risk', 'current', 'involve', 'behavior', 'anyone', 'increase', 'security', 'board', 'seek', 'officer', 'private', 'deal', 'performance', 'fight', 'top', 'goal', 'author', 'represent', 'focus', 'drop', 'blood', 'upon', 'agency', 'nature', 'color', 'recently', 'reduce', 'movem