SELECT 'AFTER' AS stage,
       (SELECT count(*) FROM vocab_words) AS words,
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet4')) AS bank_links;

