       (SELECT count(*) FROM vocab_words) = 3814 AS ok
UNION ALL
SELECT 'cet4_links = 3814',
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet4')) = 3814;

